// Converts the UI images to LVGL C images.
//
//     node tools/convert-images.mjs
//
// Sources are SVGs in firmware/assets/. Each is rendered at a fixed width with resvg (installed on demand into
// tools/.cache/, git-ignored, pinned), optionally recoloured, and written to firmware/main/ui/images/ as an ARGB8888
// lv_image_dsc_t, with Images.hpp declaring them. Generated files are committed; rerun this after changing anything below.
//
// Needs Node.js; resvg-js is installed with npm at a pinned version.

import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const RESVG = "@resvg/resvg-js@2.6.2";

// npm is a .cmd script on Windows, which can't be run without a shell; run npm's npm-cli.js with node instead
const npmCommand =
    process.platform === "win32"
        ? [process.execPath, join(dirname(process.execPath), "node_modules", "npm", "bin", "npm-cli.js")]
        : ["npm"];

const repositoryDirectory = join(dirname(fileURLToPath(import.meta.url)), "..");
const sourceDirectory = join(repositoryDirectory, "firmware", "assets");
const outputDirectory = join(repositoryDirectory, "firmware", "main", "ui", "images");
const cacheDirectory = join(repositoryDirectory, "tools", ".cache", "images");

// Images: C name → source SVG, width in pixels, and colours to replace (the SVG's own fill → ours)
const IMAGES = [
    // None yet. Example entry:
    // { name: "face_happy", file: "face-happy.svg", width: 400, recolor: { "#000000": "#E8ECF1" } },
];

// Install resvg into the cache once
function loadResvg() {
    const packageDirectory = join(cacheDirectory, "node_modules", "@resvg", "resvg-js");

    if (!existsSync(packageDirectory)) {
        mkdirSync(cacheDirectory, { recursive: true });
        console.log(`Installing ${RESVG}`);
        execFileSync(npmCommand[0], [...npmCommand.slice(1), "install", "--prefix", cacheDirectory, "--no-save", RESVG], {
            stdio: "inherit",
        });
    }

    return createRequire(join(cacheDirectory, "package.json"))("@resvg/resvg-js");
}

// Rendered RGBA (straight alpha) → LVGL ARGB8888 bytes, which are B, G, R, A in memory
function toArgb8888(pixels) {
    const bytes = Buffer.alloc(pixels.length);

    for (let index = 0; index < pixels.length; index += 4) {
        bytes[index] = pixels[index + 2];
        bytes[index + 1] = pixels[index + 1];
        bytes[index + 2] = pixels[index];
        bytes[index + 3] = pixels[index + 3];
    }

    return bytes;
}

function writeImage(image, width, height, bytes) {
    const lines = [];

    for (let offset = 0; offset < bytes.length; offset += 32) {
        const row = [...bytes.subarray(offset, offset + 32)].map((byte) => `0x${byte.toString(16).padStart(2, "0")}`);
        lines.push(`    ${row.join(",")},`);
    }

    const source = `// Generated by tools/convert-images.mjs from firmware/assets/${image.file}; do not edit
#include "lvgl.h"

static const uint8_t ${image.name}_data[] = {
${lines.join("\n")}
};

const lv_image_dsc_t ${image.name} = {
    .header =
        {
            .magic = LV_IMAGE_HEADER_MAGIC,
            .cf = LV_COLOR_FORMAT_ARGB8888,
            .flags = 0,
            .w = ${width},
            .h = ${height},
            .stride = ${width * 4},
            .reserved_2 = 0,
        },
    .data_size = sizeof(${image.name}_data),
    .data = ${image.name}_data,
    .reserved = NULL,
};
`;

    writeFileSync(join(outputDirectory, `${image.name}.c`), source);
}

const { Resvg } = loadResvg();
mkdirSync(outputDirectory, { recursive: true });
const declarations = [];

for (const image of IMAGES) {
    let svg = readFileSync(join(sourceDirectory, image.file), "utf8");

    // A crop: a new view box, with width and height to match its aspect ratio
    if (image.viewBox) {
        const [, , boxWidth, boxHeight] = image.viewBox.split(" ");
        svg = svg
            .replace(/viewBox="[^"]*"/, `viewBox="${image.viewBox}"`)
            .replace(/width="[^"]*"/, `width="${boxWidth}"`)
            .replace(/height="[^"]*"/, `height="${boxHeight}"`);
    }

    for (const [from, to] of Object.entries(image.recolor ?? {})) {
        svg = svg.replaceAll(new RegExp(from, "gi"), to);
    }

    const rendered = new Resvg(svg, { fitTo: { mode: "width", value: image.width } }).render();
    writeImage(image, rendered.width, rendered.height, toArgb8888(rendered.pixels));
    declarations.push(`extern const lv_image_dsc_t ${image.name}; // ${rendered.width}×${rendered.height}, ${image.file}`);
    console.log(`${image.name}: ${rendered.width}×${rendered.height}`);
}

writeFileSync(
    join(outputDirectory, "Images.hpp"),
    `// Generated by tools/convert-images.mjs; do not edit
#pragma once

#include "lvgl.h"

extern "C" {
${declarations.join("\n")}
}
`,
);
